ruleToc.chapterList:
.chapter-list@li@a||.chapterList.0@li@a||li a
<js>
if(String(src).match(/验证码不对/)){
result=[{"text":"右上角三点刷新重新获取验证码"}]
}else{result=result}
if(baseUrl.match(/\/\d+/)){	java.setContent(result.toArray().reverse().join(""))
	result = java.getElement("a")
	}else{
		result=result
		}
</js>

class.chapterlist.-1@ul@li@a
<js>
List=[];
sectionPage=result;
aid=baseUrl.match(/\/\d+\/(\d+)\//)[1];
option={
	"method":"POST",
	"body":"more="+1+"&aid="+aid
	};
url='https://www.ah123z.com/modules/article/reader.php,'+JSON.stringify(option)
result=java.ajax(url);
result=result.split("\</li\>").map(x=>x+"</li>");
for(i=0;i<=sectionPage.length-1;i++){
		if(i!==30){
			List.push({
		    "name":sectionPage[i].text(),
		    "link":sectionPage[i].attr('href')
		  })
		}else{
				for(j=0;j<=result.length-1;j++){
			 	 List.push({
		   "name":result[j].match(/(href=.*\>(.*?)\<\/a\>)/)[2],
		     "link":result[j].match(/href="(.*)"/)[1]
		    })
			 	}
			}
	}
	List
</js>

